import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static int nextInt() {
        while (buf[pos] <= ' ') pos++;
        int r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt();
        // lim[a] = smallest b over forbidden pairs (a, b) with a < b.
        int[] lim = new int[n + 2];
        java.util.Arrays.fill(lim, n + 1);
        for (int i = 0; i < m; i++) {
            int a = nextInt(), b = nextInt();
            if (a > b) {
                int t = a;
                a = b;
                b = t;
            }
            lim[a] = Math.min(lim[a], b);
        }
        // Scan l from n down to 1; right is the suffix minimum of lim, the first invalid right end.
        long ans = 0;
        int right = n + 1;
        for (int l = n; l >= 1; l--) {
            right = Math.min(right, lim[l]);
            ans += right - l;
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

func main() {
	data, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	pos := 0
	nextInt := func() int {
		for data[pos] <= ' ' {
			pos++
		}
		r := 0
		for pos < len(data) && data[pos] > ' ' {
			r = r*10 + int(data[pos]-'0')
			pos++
		}
		return r
	}
	n, m := nextInt(), nextInt()
	// lim[a] = smallest b over forbidden pairs (a, b) with a < b.
	lim := make([]int, n+2)
	for i := range lim {
		lim[i] = n + 1
	}
	for i := 0; i < m; i++ {
		a, b := nextInt(), nextInt()
		if a > b {
			a, b = b, a
		}
		lim[a] = min(lim[a], b)
	}
	// Scan l from n down to 1; right is the suffix minimum of lim, the first invalid right end.
	var ans int64
	right := n + 1
	for l := n; l >= 1; l-- {
		right = min(right, lim[l])
		ans += int64(right - l)
	}
	fmt.Println(ans)
}
